export default function CommentsBottomSheet({
  isVisible,
  onClose,
  postId,
}: CommentsBottomSheetProps) {
  const bottomSheetRef = useRef<BottomSheet>(null);
  const [comment, setComment] = useState('');
  const { data: commentsData, isLoading: loading, error } = useComments(postId.toString());
  const addCommentMutation = useAddComment();

  // Transform the data to match the expected format
  const comments: Comment[] = commentsData?.map((comment: any) => ({
    id: comment.id,
    user: {
      id: comment.user.id,
      name: comment.user.name,
      username: comment.user.username,
      email: comment.user.email,
      avatar: comment.user.avatar,
    },
    text: comment.content,
    timeAgo: comment.createdAt ? new Date(comment.createdAt).toLocaleDateString() : 'Unknown',
  })) || [];

  const handleSendComment = async () => {
    if (comment.trim()) {
      try {
        await addCommentMutation.mutateAsync({
          postId: postId.toString(),
          content: comment.trim(),
        });
        setComment('');
      } catch (err) {
        console.error('Failed to send comment:', err);
      }
    }
  };

if (error) {
  return (
    <View style={styles.errorContainer}>
      <Text style={styles.errorText}>{error?.message || 'Failed to load comments'}</Text>
    </View>
  );
}

const SocialFeedContent = ({ filter }: { filter: 'following' | 'popular' | 'discover' }) => {
  const { data: postsData, isLoading: loading, error } = useFeed();
  const router = useRouter();

  // Transform API data to SocialPost format
  const posts: SocialPost[] = postsData?.map((post: any) => ({
    id: post.id,
    user: {
      id: post.user.id,
      name: post.user.name,
      username: post.user.username,
      email: post.user.email,
      avatar: post.user.avatar,
    },
    media: {
      id: post.movie?.tmdbId || post.id,
      title: post.movie?.title || 'Unknown',
      posterUrl: post.movie?.posterPath || '',
      type: post.movie?.mediaType || 'movie',
      year: post.movie?.releaseDate ? new Date(post.movie.releaseDate).getFullYear() : 2024,
      genres: post.movie?.genres || [],
      rating: post.rating || 0,
      description: post.movie?.overview || '',
      releaseDate: post.movie?.releaseDate || '',
      duration: post.movie?.runtime || 0,
      progress: {
        current: 0,
        total: 100,
      },
      status: 'Completed',
      rewatches: 0,
      favorite: false,
    },
    rating: post.rating || 0,
    review: post.content || '',
    timeAgo: post.createdAt ? new Date(post.createdAt).toLocaleDateString() : 'Unknown',
    likes: post.likes || 0,
    comments: post.comments || 0,
  })) || [];

if (error) {
  return (
    <View style={styles.errorContainer}>
      <Text style={styles.errorText}>Something went wrong</Text>
      <Text style={styles.errorSubtext}>{error?.message || 'Failed to load social feed'}</Text>
    </View>
  );
}

