const [selectedFilters, setSelectedFilters] = React.useState<Record<string, string[]>>({});

// Get data from queries
const {
  data: watchlistData,
  isLoading: watchlistLoading,
  error: watchlistError,
} = useWatchlist();
const { data: moviesData, isLoading: moviesLoading, error: moviesError } = useUserMovies();
const {
  data: analyticsData,
  isLoading: analyticsLoading,
  error: analyticsError,
} = useUserAnalytics();

// Transform watchlist data to Media format
const watchlistContent: Media[] = React.useMemo(() => {
  return watchlistData?.map((item: any) => ({
    id: item.tmdbId,
    title: item.title,
    posterUrl: item.posterPath || '',
    type: item.mediaType,
    year: new Date(item.createdAt).getFullYear(),
    genres: item.genres || [],
    rating: item.rating,
    description: item.overview || '',
    releaseDate: item.releaseDate || '',
    duration: item.runtime || 0,
    progress: {
      current: 0,
      total: 100,
    },
    status: 'Planning to Watch',
    rewatches: 0,
    favorite: false,
  })) || [];
}, [watchlistData]);

// Transform watched movies data to Media format
const watchedContent: Media[] = React.useMemo(() => {
  return moviesData
    ?.filter((item: any) => item.watchedAt)
    ?.map((item: any) => ({
      id: item.tmdbId,
      title: item.title,
      posterUrl: item.posterPath || '',
      type: item.mediaType,
      year: item.releaseDate ? new Date(item.releaseDate).getFullYear() : 2024,
      genres: item.genres || [],
      rating: item.rating,
      description: item.overview || '',
      releaseDate: item.releaseDate || '',
      duration: item.runtime || 0,
      progress: {
        current: 100,
        total: 100,
      },
      status: 'Completed',
      rewatches: item.rewatches || 0,
      favorite: item.favorite || false,
      dateWatched: item.watchedAt,
    })) || [];
}, [moviesData]);

// For now, inProgressContent is empty as we don't have a specific API for it
const inProgressContent: Media[] = [];

const loading = watchlistLoading || moviesLoading || analyticsLoading;
const error = watchlistError || moviesError || analyticsError;

